// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

class PackedExecutableFallbackTierTest {

	@Test
	void saturatedCostedJoinOutranksTheExecutableLogicalFallback() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern left = new StatementPattern(Var.of("person"),
				Var.of("leftPredicate", values.createIRI("urn:left")), Var.of("leftValue"));
		StatementPattern right = new StatementPattern(Var.of("person"),
				Var.of("rightPredicate", values.createIRI("urn:right")), Var.of("rightValue"));
		PackedQuery query = PackedQueryCodec.encodeForPlanning(new Join(left, right));
		int relationCount = query.relationCount();
		PackedMemo memo = new PackedMemo(query, query.symbolCount(), relationCount, relationCount, 4, relationCount,
				relationCount * 2);
		PackedCostModel saturatedCosts = (queryView, relationId) -> 4.0e307d;
		PackedIncumbentSearch search = new PackedIncumbentSearch(query, memo,
				new PackedSearchBudget(Long.MAX_VALUE, Long.MAX_VALUE), true, saturatedCosts);

		int rootWinnerId = search.build();
		int physicalExpressionId = memo.winnerPhysicalExpressionId(rootWinnerId);

		assertEquals(Double.MAX_VALUE, memo.winnerTotalCost(rootWinnerId));
		assertNotEquals(1, memo.physicalImplementationForm(physicalExpressionId),
				"A real costed join must outrank the executable-only logical fallback even when both costs saturate");
	}

	@Test
	void fallbackOnlyGoalRemainsExecutable() {
		PackedWinnerTable winners = new PackedWinnerTable(2, 2, 2, 1);

		int winnerId = winners.offerExecutableFallbackWithMetadata(1, 1, 0, 0, 0, 10, 101, 1.0d, 20.0d,
				20.0d, new int[] { 7 }, 0, 1);

		assertEquals(10, winners.physicalExpressionId(winnerId));
		assertEquals(20.0d, winners.totalCost(winnerId));
		assertEquals(7, winners.childWinnerId(winnerId, 0));
	}

	@Test
	void saturatedCostedCandidateReplacesSaturatedFallback() {
		PackedWinnerTable winners = new PackedWinnerTable(2, 2, 2, 1);
		int winnerId = winners.offerExecutableFallbackWithMetadata(1, 1, 0, 0, 0, 10, 101, 1.0d,
				Double.MAX_VALUE, Double.MAX_VALUE, new int[] { 7 }, 0, 1);

		assertEquals(winnerId, winners.offerWithMetadata(1, 1, 0, 0, 0, 20, 202, 1.0d, Double.MAX_VALUE,
				Double.MAX_VALUE, new int[] { 8 }, 0, 1));
		assertEquals(20, winners.physicalExpressionId(winnerId));
		assertEquals(8, winners.childWinnerId(winnerId, 0));
	}

	@Test
	void laterCheaperFallbackCannotReplaceACostedWinner() {
		PackedWinnerTable winners = new PackedWinnerTable(2, 2, 2, 1);
		int winnerId = winners.offerWithMetadata(1, 1, 0, 0, 0, 20, 202, 1.0d, Double.MAX_VALUE,
				Double.MAX_VALUE, new int[] { 8 }, 0, 1);

		assertEquals(winnerId, winners.offerExecutableFallbackWithMetadata(1, 1, 0, 0, 0, 10, 101, 0.0d, 1.0d,
				1.0d, new int[] { 7 }, 0, 1));
		assertEquals(20, winners.physicalExpressionId(winnerId));
		assertEquals(Double.MAX_VALUE, winners.totalCost(winnerId));
		assertEquals(8, winners.childWinnerId(winnerId, 0));
	}

	@Test
	void cheaperFallbackRefreshesTheFallbackWinner() {
		PackedWinnerTable winners = new PackedWinnerTable(2, 2, 2, 1);
		int winnerId = winners.offerExecutableFallbackWithMetadata(1, 1, 0, 0, 0, 10, 101, 2.0d, 20.0d,
				20.0d, new int[] { 7 }, 0, 1);

		assertEquals(winnerId, winners.offerExecutableFallbackWithMetadata(1, 1, 0, 0, 0, 10, 202, 1.0d, 10.0d,
				10.0d, new int[] { 8 }, 0, 1));
		assertEquals(10.0d, winners.totalCost(winnerId));
		assertEquals(202, winners.physicalMetadataId(winnerId));
		assertEquals(8, winners.childWinnerId(winnerId, 0));
	}

	@Test
	void equalSaturatedFallbackRefreshesMetadataAndChildrenForTheSamePhysicalIdentity() {
		PackedWinnerTable winners = new PackedWinnerTable(2, 2, 2, 1);
		int winnerId = winners.offerExecutableFallbackWithMetadata(1, 1, 0, 0, 0, 10, 101, 1.0d,
				Double.MAX_VALUE, Double.MAX_VALUE, new int[] { 7 }, 0, 1);

		assertEquals(winnerId, winners.offerExecutableFallbackWithMetadata(1, 1, 0, 0, 0, 10, 202, 1.0d,
				Double.MAX_VALUE, Double.MAX_VALUE, new int[] { 8 }, 0, 1));
		assertEquals(202, winners.physicalMetadataId(winnerId),
				"Canonical-spine fallback refresh must publish current physical metadata");
		assertEquals(8, winners.childWinnerId(winnerId, 0),
				"Canonical-spine fallback refresh must publish current child winners");
	}
}
